% Smoke tests of the datamunge Octave binding generated by Rosetta (just test-octave): run with
% the directory holding __datamunge__.oct and +datamunge on the load path, from the repository
% root (the Doubler and Failing subclasses live beside this file).
1;

function check (ok, what)
  global checks
  checks = checks + 1;
  if ! (islogical (ok) || isnumeric (ok)) || isempty (ok) || ! all (ok(:))
    error ('test_datamunge:failed', 'check failed: %s', what);
  end
end

global checks
checks = 0;
here = fileparts (mfilename ('fullpath'));
if isempty (here) || ! exist (fullfile (here, 'Doubler.m'), 'file')
  here = fullfile (pwd, 'tests', 'octave');
end
addpath (here);

% Smoke test: call into the oct-file (hello prints through C++ std::cout).
datamunge.hello ();
check (exist ('__datamunge__') == 3, 'the oct-file is loaded');

% std::vector<double> and std::pair<double,double> round trips.
v = datamunge.make_dvector (1, 2, 3);
check (isequal (v, [1 2 3]), 'std::vector<double> is a row vector');
check (datamunge.sum_dvector (v) == 6 && datamunge.sum_dvector ([0.5; 1.5]) == 2, 'sum_dvector');
p = datamunge.make_dpair (1.25, 2.75);
check (iscell (p) && p{1} == 1.25 && p{2} == 2.75, 'std::pair is a cell');
check (datamunge.sum_dpair (p) == 4, 'sum_dpair');

% The C++ Callback class, and an Octave subclass overriding its virtual call() (a director).
cb = datamunge.Callback ();
check (datamunge.call_with_callback (3, cb) == 3, 'native Callback');
check (isequal (datamunge.map_dvector_with_callback ([1 2 3], cb), [1 2 3]), 'native map');
twice = Doubler ();
check (isa (twice, 'datamunge.Callback') && datamunge.call_with_callback (3, twice) == 6, 'the Octave override runs');
check (sum (datamunge.map_dvector_with_callback ([1 2 3], twice)) == 12, 'override from C++ loops');

% An error raised by an override reaches the caller with its identifier.
try
  datamunge.call_with_callback (1, Failing ());
  err = [];
catch err
end
check (! isempty (err) && strcmp (err.identifier, 'Failing:call') && ! isempty (strfind (err.message, 'from Octave')), 'the Octave error propagates');

% C++ exceptions become Octave errors with an identifier.
try
  datamunge.runif (1, 0, 3);
  err = [];
catch err
end
check (! isempty (err) && strcmp (err.identifier, 'datamunge:invalid_argument'), 'C++ exceptions raise datamunge:invalid_argument');

% Classes and methods.
frame = datamunge.DataFrame ();
frame.add_numeric_column ('x', [1 2 3]);
check (frame.nrows () == 3 && isa (frame, 'datamunge.NativeObject'), 'DataFrame');
check (isequal (frame.columns (), {'x'}), 'std::vector<std::string> is a cellstr');
iris = datamunge.Data.iris ();
check (iris.nrows () == 150 && any (strcmp (iris.columns (), 'Species')), 'the policy module Data is the subpackage datamunge.Data');
delete (frame);
check (isclosed (frame), 'delete frees an object');

% The generated .m files carry the C++ documentation as Octave help text.
text = get_help_text ('datamunge.seql');
check (! isempty (strfind (text, 'evenly spaced')) && ! isempty (strfind (text, 'r = datamunge.seql (from, to, n)')), 'help text');

printf ('test_datamunge.m: all %d checks passed\n', checks);
